import hashlib,pathlib,re,shutil
def recover(candidates,approved,live,approved_delta,target):
    live=pathlib.Path(live);target=pathlib.Path(target)
    if target.exists():raise FileExistsError(target)
    def digest(root,name):
        if not isinstance(name,str) or re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*[.]json',name) is None:raise ValueError('explicit top-level JSON file required')
        file=pathlib.Path(root)/name
        if not file.is_file() or file.is_symlink():raise ValueError('regular immutable input required')
        return hashlib.sha256(file.read_bytes()).hexdigest()
    if not candidates or len({c['id'] for c in candidates})!=len(candidates):raise ValueError('unique candidates required')
    for name,sha in approved_delta.items():
        if digest(live,name)!=sha:raise ValueError('approved live delta changed')
    selected=None
    for candidate in sorted(candidates,key=lambda c:c['time'],reverse=True):
        manifest=approved.get(candidate['id'])
        if not manifest:continue
        try:valid=all(digest(candidate['path'],name)==sha for name,sha in manifest.items())
        except ValueError:valid=False
        if valid:selected=(candidate,manifest);break
    if selected is None:raise ValueError('no approved intact recovery point')
    candidate,manifest=selected
    conflicts=sorted(name for name,sha in approved_delta.items() if name in manifest and sha!=manifest[name])
    added=sorted(set(approved_delta)-set(manifest))
    target.mkdir();baseline=target/'baseline';pending=target/'pending-delta';baseline.mkdir();pending.mkdir()
    for name in manifest:shutil.copy2(pathlib.Path(candidate['path'])/name,baseline/name)
    for name in approved_delta:shutil.copy2(live/name,pending/name)
    return {'selected':candidate['id'],'conflicts':conflicts,'added':added}
```

